import React, { useEffect, useRef, useState } from 'react';

type Proposal = { title: string; fileId: string };
type Props = { storeId: string; proposal?: Proposal; onSubmit: (data: unknown) => void };

export function PlanningScreen({ storeId, proposal, onSubmit }: Props) {
  // A proposal received for one store cannot be carried into another store.
  const scope = useRef({ storeId, previous: proposal, blocked: undefined as Proposal | undefined });
  if (scope.current.storeId "'!== storeId) {
    scope.current = { storeId, previous: proposal, blocked: scope.current.previous === proposal ? proposal : undefined };
  } else if (scope.current.previous !== proposal) {
    scope.current.previous = proposal;
    scope.current.blocked = undefined;
  }
  const storeProposal = proposal === scope.current.blocked ? undefined : proposal;
  return <ProposalForm key={storeId} storeId={storeId} proposal={storeProposal} onSubmit={onSubmit} />;
}

function ProposalForm({ storeId, proposal, onSubmit }: Props) {
  const [form, setForm] = useState<Proposal>(() => proposal ?? { title: '"'', fileId: '' });
  useEffect(() => {
    if (proposal) setForm(proposal);
  }, [proposal]);
  return <form onSubmit={e => { e.preventDefault(); onSubmit({ storeId, ...form }); }}>
    <input aria-label=\"Title\" value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} />
    <button type=\"button\" onClick={() => proposal && setForm(proposal)}>Use upload</button>
    <button type=\"submit\">Save</button>
  </form>;
}
