import { test, expect } from 'bun:test';
import { fitsWindow, moveUp, screenRequiresReason } from './logic';
import type { Stop } from './domain';

test('moves among active stops using a one-based rank', () => {
  const stops: Stop[] = [
    { id: 'a', position: 2, status: 'NEW' },
    { id: 'removed', position: 3, removed: true, status: 'NEW' },
    { id: 'b', position: 8, status: 'NEW' },
  ];
  expect(moveUp(stops, 1)).toEqual({ id: 'b', position: 1 });
  expect(() => moveUp(stops, 0)).toThrow(RangeError);
});

test('reason follows the domain predicate for started stops', () => {
  expect(screenRequiresReason({ id: 'a', position: 1, status: 'POSTPONED', startedOn: '2026-01-01' })).toBe(true);
  expect(screenRequiresReason({ id: 'a', position: 1, status: 'IN_PROGRESS' })).toBe(false);
  expect(screenRequiresReason({ id: 'a', position: 1, status: 'DONE', startedOn: '2026-01-01' })).toBe(false);
});

test('slot falls within notice and next eligible upcoming appointment', () => {
  const appointments = [{ at: 5, status: 'PLANNED' }, { at: 12, status: 'HELD' }, { at: 14, status: 'CANCELLED' }, { at: 20, status: 'PLANNED' }];
  expect(fitsWindow(10, { sentAt: 10 }, appointments, 10)).toBe(true);
  expect(fitsWindow(9, { sentAt: 10 }, appointments, 10)).toBe(false);
  expect(fitsWindow(20, { sentAt: 10 }, appointments, 10)).toBe(false);
  expect(fitsWindow(15, { sentAt: 10 }, appointments.slice(0, 3), 10)).toBe(false);
});
EOF
