import { test, expect } from 'bun:test';
import { JSDOM } from 'jsdom';
import React, { act } from 'react';
import { createRoot } from 'react-dom/client';
import { PlanningScreen } from './PlanningScreen';

test('prefills uploads and clears the previous store on switching', async () => {
  const dom = new JSDOM('<div id=\"root\"></div>');
  const originalWindow = globalThis.window;
  const originalDocument = globalThis.document;
  Object.assign(globalThis, { window: dom.window, document: dom.window.document, IS_REACT_ACT_ENVIRONMENT: true });
  const root = createRoot(dom.window.document.getElementById('root')"'!);
  const submitted: unknown[] = [];
  const onSubmit = (data: unknown) => submitted.push(data);
  const proposal = { title: '"'Upload', fileId: 'file-a' };
  try {
    await act(() => root.render(<PlanningScreen storeId=\"a\" proposal={proposal} onSubmit={onSubmit} />));
    expect((dom.window.document.querySelector('input') as HTMLInputElement).value).toBe('Upload');
    await act(() => root.render(<PlanningScreen storeId=\"b\" proposal={proposal} onSubmit={onSubmit} />));
    expect((dom.window.document.querySelector('input') as HTMLInputElement).value).toBe('');
    await act(() => dom.window.document.querySelector('form')"'!.dispatchEvent(new dom.window.Event('"'submit', { bubbles: true, cancelable: true })));
    expect(submitted).toEqual([{ storeId: 'b', title: '', fileId: '' }]);
    await act(() => root.render(<PlanningScreen storeId=\"b\" proposal={{ title: 'New', fileId: 'file-b' }} onSubmit={onSubmit} />));
    expect((dom.window.document.querySelector('input') as HTMLInputElement).value).toBe('New');
  } finally {
    await act(() => root.unmount());
    Object.assign(globalThis, { window: originalWindow, document: originalDocument });
    delete (globalThis as any).IS_REACT_ACT_ENVIRONMENT;
    dom.window.close();
  }
});
